int git_index_entry_read(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    const git_index_entry *entry = buffer;
    git_index_entry *new_entry;
    size_t entry_size = sizeof(git_index_entry);

    if (buffer_size < entry_size) {
        return -1;
    }

    new_entry = (git_index_entry *)malloc(entry_size);
    if (!new_entry) {
        return -1;
    }

    memcpy(new_entry, entry, entry_size);

    if (new_entry->flags & GIT_INDEX_ENTRY_FLAG_HASH_VALID) {
        if (git_oid_is_zero(&new_entry->oid)) {
            free(new_entry);
            return -1;
        }
    }

    if (new_entry->flags & GIT_INDEX_ENTRY_FLAG_CASE_MODIFIED) {
        new_entry->flags &= ~GIT_INDEX_ENTRY_FLAG_CASE_MODIFIED;
    }

    if (new_entry->flags & GIT_INDEX_ENTRY_FLAG_PATH_COMPRESSED) {
        size_t last_len = strlen(last);
        size_t path_len = strlen(new_entry->path) + last_len + 1;
        char *path = (char *)malloc(path_len);

        if (!path) {
            free(new_entry);
            return -1;
        }

        snprintf(path, path_len, "%s/%s", last, new_entry->path);
        free(new_entry->path);
        new_entry->path = path;
    }

    *out = new_entry;
    *out_size = entry_size;

    return 0;
}

int git_index_entry_from_buffer(git_index_entry **out, size_t *out_size,
                                git_index *index, const void *buffer,
                                size_t buffer_size, const char *last)
{
    git_index_entry *entry;
    const size_t entry_size = sizeof(git_index_entry);
    size_t path_length;

    if (buffer_size < entry_size) {
        return -1;
    }

    entry = (git_index_entry *)malloc(entry_size);
    if (entry == NULL) {
        return -1;
    }

    memcpy(entry, buffer, entry_size);

    path_length = strlen((const char *)buffer + entry_size) + 1;
    entry->path = (char *)malloc(path_length);
    if (entry->path == NULL) {
        free(entry);
        return -1;
    }

    if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
        char full_path[PATH_MAX];
        snprintf(full_path, sizeof(full_path), "%s/%s", last, entry->path);
        free(entry->path);
        entry->path = strdup(full_path);
        if (entry->path == NULL) {
            free(entry);
            return -1;
        }
    }

    *out = entry;
    *out_size = entry_size + path_length;

    return 0;
}

int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (!buffer || buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));
    *out_size = sizeof(git_index_entry);

    if (entry->flags & GIT_INDEX_ENTRY_UNCOPIED) {
        size_t path_len = strlen(entry->path) + 1;
        char *path = (char *)malloc(path_len);
        if (!path) {
            free(entry);
            return -1;
        }

        if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
            char full_path[1024];
            snprintf(full_path, sizeof(full_path), "%s/%s", last, entry->path);
            free(entry->path);
            entry->path = strdup(full_path);
            if (!entry->path) {
                free(path);
                free(entry);
                return -1;
            }
        } else {
            entry->path = path;
        }
    }

    if (!entry->path || entry->sha1[0] == 0) {
        free(entry->path);
        free(entry);
        return -1;
    }

    *out = entry;
    return 0;
}

int git_index_entry_read(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (!buffer || buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(buffer_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, buffer_size);

    if (entry->flags & GIT_INDEX_ENTRY_COMPRESSED) {
        if (!last || strlen(last) + strlen(entry->path) + 1 > buffer_size) {
            free(entry);
            return -1;
        }

        char full_path[buffer_size];
        snprintf(full_path, buffer_size, "%s/%s", last, entry->path);
        free(entry->path);
        entry->path = strdup(full_path);
        if (!entry->path) {
            free(entry);
            return -1;
        }
    }

    if (entry->mode == 0) {
        free(entry->path);
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = buffer_size;
    return 0;
}

int git_index_entry_read(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    git_index_entry *entry;
    size_t entry_size = sizeof(git_index_entry);

    if (buffer_size < entry_size) {
        return -1;
    }

    entry = (git_index_entry *)malloc(entry_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, entry_size);

    if (entry->flags & GIT_INDEX_FLAG_HASH) {
        if (entry->path) {
            free(entry->path);
        }
        entry->path = strdup(last);
        if (!entry->path) {
            free(entry);
            return -1;
        }
    } else {
        size_t path_len = strlen(entry->path);
        if (entry->path) {
            free(entry->path);
        }
        entry->path = (char *)malloc(path_len + 1);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        memcpy(entry->path, last, path_len + 1);
    }

    *out = entry;
    *out_size = entry_size;
    return 0;
}
